<span class="line"><span style="color:#D73A49;">var</span><span style="color:#24292E;"> birthday </span><span style="color:#D73A49;">=</span><span style="color:#D73A49;"> new</span><span style="color:#6F42C1;"> Date</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&quot;1995-12-17T03:24:00&quot;</span><span style="color:#24292E;">);</span></span>
